// Lifts the program of a Blitz executable (x86) to LLVM IR that is linked with the BlitzLLVM runtime.
//
// The IR keeps the memory model of the original: the program, its variables, its stack and the objects of its types live in an arena
// (code_runtime/source/blitz32.h) where every address is 32 bits, so that the code is translated instruction by instruction and the
// layout of Types, Dim arrays and the stack stays what the code expects. Calls into the runtime go through thunks that read the
// arguments from the stack, like the original (stdcall), and call the function of BlitzLLVM.
#pragma once
#include <string>
#include <vector>
#include "module.hpp"

namespace blitz::recompiler {
	struct lift_options {
		bool keep_going = true;  // Functions that can't be translated raise a runtime error when they are called, instead of failing the whole program
		bool verbose    = false;
	};

	struct lift_result {
		std::string              ir;
		std::vector<std::string> problems;     // One line for each function that was not translated, and why
		size_t                   functions = 0;
		size_t                   instructions = 0;
		size_t                   failed_functions = 0;
	};

	lift_result lift(blitz_module const& program, lift_options const& options);
} // namespace blitz::recompiler
